namespace {
BackendIdentity hardware(bool joint=false){BackendIdentity h;h.hardware_contract=digest(11);h.bit=digest(12);h.xsa=digest(13);h.compatible=digest(14);h.device_generation=1;h.provider_flags=1;if(joint){auto parse=[](const char*s){Digest d{};for(unsigned i=0;i<32;i++){auto n=[](char c){return unsigned(c<='9'?c-'0':c-'a'+10);};d[i]=(n(s[2*i])<<4)|n(s[2*i+1]);}return d;};h.provider_flags=4;h.hardware_contract=parse("1bf11d26789e7c602f9c05a5ecc97e2605ac7807deade8f4bfc549487f45ec5d");h.bit=parse("94ae9d3e6eb73ba55a8eec8c802e3818cd6b3a9be7e60542da5ae9459e3579e1");h.xsa=parse("02e68160e21b01621fde1eac6e472810e0fe50cd1842acb3ab63469314355e94");h.compatible=parse("f670c653a37361f05f57c14eecd53dea1b87556489a2c1314efd208d715826dc");}return h;}
WorkRequest display_request(const char*id){auto r=request(id,1,WorkKind::CPU,AppKind::IMAGE);r.cpu_bytes=4096;r.resident_bytes=1024;return r;}
PublishedResult output(const WorkItem&w){auto p=producer(w.request.request_id.c_str());p.lease.producer=w.request;p.lease.app=w.app;p.lease.model=digest(1);p.lease.plan=digest(2);p.lease.hardware=hardware().hardware_contract;return p;}
struct Port:ExecutionPort {
 BackendIdentity identity=hardware();int fd=-1,runs=0,retired=0;std::function<Result<void>(const WorkItem&,ExecutionReceipt&)>hook;
 Result<BackendIdentity>probe(int f,BackendMode m)override{need(f==fd&&m==BackendMode::COMPUTE_V2,"one owner fd");return Result<BackendIdentity>::success(identity);}
 Result<void>execute(int f,const WorkItem&w,vxnn::CpuPool*pool,ExecutionReceipt&r)override{need(f==fd&&pool,"same owner/sharedCPU pool");++runs;r.outcome=outcome(w);r.output=output(w);r.output->lease.hardware=identity.hardware_contract;return hook?hook(w,r):Result<void>::success();}
 Result<void>retire_request(int f,RequestKey)override{need(f==fd,"same retirement owner");++retired;return Result<void>::success();}
};
struct Fixture {
 char dir[64]="/tmp/vx-native-display-XXXXXX";std::shared_ptr<DeviceOwner>owner;std::shared_ptr<Port>port=std::make_shared<Port>();std::shared_ptr<Runtime>rt;StartupContext ctx;FakeDisplay screen;unsigned stages=0,publications=0,observations=0;std::optional<DisplayObservation>last;
 Fixture(bool joint=false){port->identity=hardware(joint);need(mkdtemp(dir)!=nullptr,"own private directory");ServiceConfig config;config.private_dir=dir;owner=get(DeviceOwner::acquire(config,[](const std::string&){return Result<int>::success(open("/dev/null",O_RDWR|O_CLOEXEC));}),"sole test owner");port->fd=owner->fd();rt=get(Runtime::start(owner,port->identity,vxnn::EvidenceScope::HOST_PROTOCOL_TEST,port,[](const ExecutionReceipt&,DeliveryStage){return Result<void>::success();},[this](const PublishedResult&){++publications;return Result<void>::success();}),"same Runtime");ctx.borrowed_fd=owner->fd();ctx.identity=port->identity;ctx.boot_id="boot";ctx.private_dir=dir;ctx.runtime=rt;ctx.results=rt->trusted_results();ctx.scope=vxnn::EvidenceScope::HOST_PROTOCOL_TEST;}
 DisplayJournal journal(){return [this](const DisplayObservation&o){++observations;last=o;return Result<void>::success();};}
 PersistResult stage(){return [this](const PublishedResult&p){++stages;need(p.binding&&p.binding->hardware==ctx.identity.hardware_contract&&!p.gpu_raw_cycles,"actual staged binding, null physical cycles");return Result<void>::success();};}
 ~Fixture(){rt.reset();owner.reset();unlink((std::string(dir)+"/owner.lock").c_str());rmdir(dir);}
};
int flow(){
 Fixture f;auto display_result=NativeDisplay::create(f.ctx,f.screen.ops(),composer(),f.journal(),f.stage());
 need(bool(display_result),"U20 actual common Runtime/DP presentation bridge required");auto display=*display_result.value;
 auto r=display_request("one");WorkItem outside_item;outside_item.request=r.request;outside_item.app=AppKind::IMAGE;auto outside=display->stage_and_present(output(outside_item),layout(),400);need(!outside&&outside.error->code==EPERM&&f.screen.next==0,"no outside-worker private stage");
 f.port->hook=[&](const WorkItem&w,ExecutionReceipt&receipt){
  auto p=*receipt.output;auto shown=display->stage_and_present(p,layout(),400);if(shown)std::printf("U20_FIRST_FRONT presented=%d had_old_front=%d old_retired=%d result=%d\n",int(shown.value->presented),int(shown.value->had_old_front),int(shown.value->old_retired),shown.value->result);else std::printf("U20_FIRST_FRONT_ERROR code=%d detail=%s\n",shown.error->code,shown.error->detail.c_str());std::fflush(stdout);need(bool(shown)&&shown.value->presented&&!shown.value->had_old_front&&shown.value->old_retired&&shown.value->old_retired_ns&&*shown.value->old_retired_ns>=*shown.value->presented_ns,"first actual C display records initial blank retirement");need(f.publications==0&&!f.rt->take_result(w.request)&&f.rt->trusted_results()->stats().staged_records==1,"KMS stage stays private until Runtime commit");return Result<void>::success();
 };
 get(f.rt->submit(r),"image request admitted to common queue");good(f.rt->run_one(),"actual Runtime and original C display flow");auto result=get(f.rt->take_result(r.request),"public output after compute and display");need(result.displayed&&result.numeric==vxnn::NumericClass::KNOWN_NUMERIC_DEVIATION&&result.raw_legacy_json=="{\"historical\":\"failure preserved\"}"&&!result.gpu_raw_cycles,"display never upgrades numeric history or physical cycles");
 auto observation=display->snapshot();need(observation.raw_events.size()==3&&observation.receipt.cookie==400&&observation.source_lease_token!=400&&!observation.pending,"raw OS/lease/logical cookies distinct and retained");good(f.rt->reap_result(r.request),"reap client only");need(f.port->retired==0,"live front pins source");
 auto two=display_request("two");f.port->hook=[&](const WorkItem&,ExecutionReceipt&receipt){auto shown=display->stage_and_present(*receipt.output,layout(),401);need(bool(shown)&&shown.value->presented&&shown.value->had_old_front&&shown.value->old_retired,"second output waits for original old front retirement");return Result<void>::success();};get(f.rt->submit(two),"next image");good(f.rt->run_one(),"original flip and retirement");need(f.port->retired==1,"old client/front released once");good(f.rt->reap_result(two.request),"new client drop");good(display->retire(),"display retires before Runtime close");need(f.port->retired==2&&f.screen.destroyed==2&&f.screen.closed==1,"both original scanouts safely destroyed");good(display->retire(),"idempotent successful close");good(f.rt->shutdown(),"common Runtime shutdown");puts("U20_COMMON_RUNTIME_PRIVATE_STAGE_ORIGINAL_C_KMS_RETIRE_PASS_HOST_NOT_DP gpu_raw_cycles=null");return 0;
}
int joint_cookie(){
 Fixture f(true);auto d=get(NativeDisplay::create(f.ctx,f.screen.ops(),composer(),f.journal(),f.stage()),"joint one DP owner");uint64_t previous=0;unsigned index=0;
 for(auto app:{AppKind::IMAGE,AppKind::P8,AppKind::NN}){
  get(f.rt->request_mode(app),"joint next complete-frame mode");get(f.rt->advance_mode(),"joint empty handoff");need(f.port->retired==int(index?index-1:0),"mode handoff preserves prior DP front");
  const auto name=std::string("joint-")+std::to_string(index);auto r=display_request(name.c_str());r.app=app;r.model=digest(uint8_t(21+index));r.resident_bytes=1024;
  f.port->hook=[&](const WorkItem&,ExecutionReceipt&receipt){receipt.output->lease.model=r.model;auto shown=d->stage_and_present(*receipt.output,layout(),201);need(bool(shown)&&shown.value->cookie==201&&shown.value->presented,"same application number across IMAGE/P8/NN must present");return Result<void>::success();};
  get(f.rt->submit(r),"joint app in selected mode");good(f.rt->run_one(),"actual common Runtime/fake KMS transition");auto observed=d->snapshot();need(observed.receipt.cookie!=previous&&observed.source_lease_token==observed.receipt.cookie,"joint common cookie allocated by unique retained source token");previous=observed.receipt.cookie;
  good(f.rt->reap_result(r.request),"drop only client hold");need(f.port->retired==int(index),"old front retired only after next presentation");++index;
 }
 good(d->retire(),"joint final front retirement");need(f.port->retired==3,"all three source lifetimes released exactly once");good(f.rt->shutdown(),"joint shared owner closes");puts("JOINT_IMAGE_P8_NN_DUPLICATE_APPLICATION_COOKIE_UNIQUE_COMMON_COOKIE_PRESERVED_FRONT_PASS_HOST_NOT_DP");return 0;
}
int mismatch(){Fixture f;auto wrong=f.ctx;int retired=0;wrong.results=store(retired);auto reject=NativeDisplay::create(wrong,f.screen.ops(),composer(),f.journal(),f.stage());need(!reject&&f.screen.opened==0,"foreign store refused before KMS open");wrong=f.ctx;wrong.scope=vxnn::EvidenceScope::REAL_BOARD;auto reject_scope=NativeDisplay::create(wrong,f.screen.ops(),composer(),f.journal(),f.stage());need(!reject_scope&&f.screen.opened==0,"foreign scope cannot lift host evidence");good(f.rt->shutdown(),"empty close");puts("U20_COMMON_DISPLAY_ROOTS_SCOPE_REJECT_PASS_HOST_NOT_DP gpu_raw_cycles=null");return 0;}
int receive_error(){Fixture f;auto d=get(NativeDisplay::create(f.ctx,f.screen.ops(),composer(),f.journal(),f.stage()),"common display");f.screen.receive_error=-EIO;auto r=display_request("failure");f.port->hook=[&](const WorkItem&,ExecutionReceipt&receipt){auto shown=d->stage_and_present(*receipt.output,layout(),900);if(!shown)return Result<void>::failure(*shown.error);return Result<void>::success();};get(f.rt->submit(r),"fault request");auto ran=f.rt->run_one();need(!ran&&ran.error->code==EIO&&f.port->runs==1&&!f.rt->take_result(r.request),"original display error returned; no output upgrade");auto snapshot=d->snapshot();need(snapshot.first_error&&snapshot.first_error->code==EIO&&snapshot.pending,"unknown presentation retains backing and raw error");auto again=d->present_result(output(WorkItem{}),layout(),901);need(!again&&again.error->code==EIO&&f.port->runs==1,"no automatic retry or successor");puts("U20_COMMON_DISPLAY_ORIGINAL_ERROR_RETAINED_NO_RETRY_PASS_HOST_NOT_DP gpu_raw_cycles=null");return 0;}
}
int main(int argc,char**argv){need(argc==2,"mode");std::string mode=argv[1];if(mode=="joint-cookie")return joint_cookie();if(mode=="flow")return flow();if(mode=="roots")return mismatch();if(mode=="error")return receive_error();return 2;}
